import { forwardRef } from "react";
import { clsx } from "clsx";
import { flip, offset, shift } from "@floating-ui/react";
import { useEditorId, useEventEditorValue } from "platejs/react";
import { useFloatingToolbar, useFloatingToolbarState } from "@platejs/floating";

import { RichTextClasses } from "../rich-text.styles";

export type RichTextFloatingToolbarProps = React.ComponentPropsWithoutRef<"div">;

export const RichTextFloatingToolbar = forwardRef<HTMLDivElement, RichTextFloatingToolbarProps>(
  ({ className, children, ...rest }, forwardedRef) => {
    const editorId = useEditorId();
    const focusedEditorId = useEventEditorValue("focus");

    const state = useFloatingToolbarState({
      editorId,
      focusedEditorId,
      floatingOptions: {
        placement: "top",
        middleware: [offset(8), flip(), shift({ padding: 8 })],
      },
    });
    const { ref, props: floatingProps, hidden } = useFloatingToolbar(state);

    if (hidden) return null;

    return (
      <div
        ref={(el) => {
          ref(el);
          if (typeof forwardedRef === "function") forwardedRef(el);
          else if (forwardedRef) forwardedRef.current = el;
        }}
        className={clsx(RichTextClasses.floatingToolbar, className)}
        {...floatingProps}
        {...rest}
      >
        {children}
      </div>
    );
  },
);

RichTextFloatingToolbar.displayName = "RichText.FloatingToolbar";
